package net.officefloor.hq.app.period;

/** The body of a fiscal year generate: the year (yyyy) as typed, the fiscal year being named FY<yyyy>. */
public record GenerateFiscalYearRequest(String year) {
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import java.util.regex.Pattern;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateGenerateFiscalYear {

    private static final Pattern YEAR = Pattern.compile("\\d{4}");

    // A year (yyyy): fiscal year FY<yyyy> starts on the first of the sheet's fiscal start month in that year and
    // runs twelve months. Each month becomes a period as the period generator makes it.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFiscalYearRequest body,
            Periods periods, Settings settings, Out<GeneratedPeriods> generatedOut) throws InvalidPeriodException {
        String year = body == null || body.year() == null ? "" : body.year().trim();
        if (!YEAR.matcher(year).matches()) {
            throw new InvalidPeriodException("The fiscal year must be a year (yyyy).");
        }
        String sheet = sheetId.trim();
        YearMonth first = YearMonth.of(Integer.parseInt(year), settings.fiscalStartMonth(sheet));
        generatedOut.set(GeneratedPeriods.months(sheet, periods.list(sheet), first, first.plusMonths(11)));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateGeneratePeriods {

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // A from and to date (yyyy-mm-dd), the to-date on or after the from-date. Each month from the from-date's to
    // the to-date's becomes a period named yyyy-mm, unless its name is taken or it shares a day with a period.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GeneratePeriodsRequest body,
            Periods periods, Out<GeneratedPeriods> generatedOut) throws InvalidPeriodException {
        LocalDate from = date(body == null ? null : body.from(), "from");
        LocalDate to = date(body.to(), "to");
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date must be on or after the from-date.");
        }
        String sheet = sheetId.trim();
        generatedOut.set(GeneratedPeriods.months(sheet, periods.list(sheet), YearMonth.from(from), YearMonth.from(to)));
    }

    private static LocalDate date(String typed, String which) throws InvalidPeriodException {
        try {
            return LocalDate.parse(typed == null ? "" : typed.trim(), ISO);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date (yyyy-mm-dd).");
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** The month periods a generate makes, in month order. */
public record GeneratedPeriods(List<Period> periods) {

    /** A period per month from {@code first} to {@code last}, each named yyyy-mm, leaving out a month whose name is taken or that shares a day with an existing period. */
    public static GeneratedPeriods months(String sheet, List<Period> existing, YearMonth first, YearMonth last) {
        List<Period> made = new ArrayList<>();
        for (YearMonth m = first; !m.isAfter(last); m = m.plusMonths(1)) {
            Period month = new Period(sheet, m.toString(), m.atDay(1), m.atEndOfMonth());
            boolean clash = existing.stream().anyMatch(p -> p.name().equals(month.name()) || p.overlaps(month));
            if (!clash) {
                made.add(month);
            }
        }
        return new GeneratedPeriods(made);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;

public class AddGeneratedPeriods {
    public void add(@Val GeneratedPeriods generated, Periods periods) {
        generated.periods().forEach(periods::add);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPeriodsGenerated {
    // Each generated period is recorded as an added one, in month order.
    public void audit(@Val GeneratedPeriods generated, ServerHttpConnection connection, Audit audit) {
        String user = Audit.user(connection);
        for (Period period : generated.periods()) {
            audit.record(Audit.line("PERIOD_ADDED", period.sheetId(), user, "period=" + period.name(),
                    "from=" + period.from(), "to=" + period.to()));
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGenerated {
    public void respond(@Val GeneratedPeriods generated, ObjectResponse<GeneratedResponse> response) {
        response.send(new GeneratedResponse(generated.periods().size()));
    }
}
