cat > $P/ValidateGenerateQuarters.java <<'EOF'
package net.officefloor.hq.app.period;

import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateGenerateQuarters {

    private static final Pattern YEAR = Pattern.compile("\\d{4}");

    // A year (yyyy): its four calendar quarters become periods named <yyyy>-Q1 to <yyyy>-Q4, each as the period
    // form would add it.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateQuartersRequest body,
            Periods periods, Out<GeneratedPeriods> generatedOut) throws InvalidPeriodException {
        String year = body == null || body.year() == null ? "" : body.year().trim();
        if (!YEAR.matcher(year).matches()) {
            throw new InvalidPeriodException("The year must be a year (yyyy).");
        }
        String sheet = sheetId.trim();
        generatedOut.set(GeneratedPeriods.quarters(sheet, periods.list(sheet), Integer.parseInt(year)));
    }
}
EOF
python3 - <<'EOF'
p='java/net/officefloor/hq/app/period/GeneratedPeriods.java'
s=open(p).read()
s=s.replace('/** The month periods a generate makes, in month order. */','/** The periods a generate makes, in date order. */')
i=s.rstrip().rfind('}')
s=s[:i]+'''
    /** The four calendar quarters of {@code year}, named yyyy-Q1 to yyyy-Q4, leaving out a quarter whose name is taken or that shares a day with an existing period. */
    public static GeneratedPeriods quarters(String sheet, List<Period> existing, int year) {
        List<Period> made = new ArrayList<>();
        for (int q = 1; q <= 4; q++) {
            YearMonth first = YearMonth.of(year, q * 3 - 2);
            Period quarter = new Period(sheet, year + "-Q" + q, first.atDay(1), first.plusMonths(2).atEndOfMonth());
            boolean clash = existing.stream().anyMatch(p -> p.name().equals(quarter.name()) || p.overlaps(quarter));
            if (!clash) {
                made.add(quarter);
            }
        }
        return new GeneratedPeriods(made);
    }
}
'''
open(p,'w').write(s)
EOF
